import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { fetchComplaints } from "../../api/complaints.api";
import { useAuth } from "../../auth/AuthContext";

// New UI Components
import GreetingBanner from "../../components/dashboard/GreetingBanner";
import NeedsAttention from "../../components/dashboard/NeedsAttention";
import QuickAccessCard from "../../components/dashboard/QuickAccessCard";
import ActivityFeed from "../../components/dashboard/ActivityFeed";

// Icons
import {
  MessageSquare,
  Wrench,
  Package,
  ShoppingCart,
  Calendar,
  Building,
  ClipboardList,
  ShieldCheck,
  UserCheck,
  Briefcase
} from "lucide-react";

export default function Dashboard() {
  const { profile } = useAuth();
  const navigate = useNavigate();

  // Keep your existing role logic
  const roleName =
    profile?.roles?.name || profile?.role || profile?.user_roles?.role || "USER";

  useEffect(() => {
    async function test() {
      try {
        await fetchComplaints();
      } catch (err) {
        console.error("Complaints fetch failed:", err.message);
      }
    }
    test();
  }, []);

  return (
    <div className="space-y-6 max-w-7xl mx-auto">

      {/* 1. Greeting & Hero Section */}
      <GreetingBanner 
        user={profile?.full_name || "Resident"} 
        role={roleName} 
      />

      {/* 2. Important Notifications / Alerts */}
      <NeedsAttention />

      {/* 3. Quick Access Grid */}
      <div>
        <h3 className="text-lg font-semibold mb-4 text-slate-800 px-1">
          Quick Access
        </h3>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          <QuickAccessCard
            title="Complaints"
            icon={<MessageSquare className="w-5 h-5" />}
            link="/complaints"
          />

          <QuickAccessCard
            title="Maintenance"
            icon={<Wrench className="w-5 h-5" />}
            link="/maintenance"
          />

          <QuickAccessCard
            title="Parcels"
            icon={<Package className="w-5 h-5" />}
            link="/my-parcels"
          />

          <QuickAccessCard
            title="Marketplace"
            icon={<ShoppingCart className="w-5 h-5" />}
            link="/marketplace"
          />

          <QuickAccessCard
            title="Worker Services"
            icon={<Briefcase className="w-5 h-5" />}
            link="/worker-services"
          />

          <QuickAccessCard
            title="Facilities"
            icon={<Building className="w-5 h-5" />}
            link="/facilities"
          />

          <QuickAccessCard
            title="Events"
            icon={<Calendar className="w-5 h-5" />}
            link="/events"
          />

          <QuickAccessCard
            title="Notices"
            icon={<ClipboardList className="w-5 h-5" />}
            link="/notices"
          />

          {/* Conditional Role-Based Access */}
          {(roleName === "SECURITY" || roleName === "ADMIN") && (
            <QuickAccessCard
              title="Gate Management"
              icon={<ShieldCheck className="w-5 h-5 text-blue-600" />}
              link="/gate"
            />
          )}

          {roleName === "ADMIN" && (
            <QuickAccessCard
              title="Seller Approvals"
              icon={<UserCheck className="w-5 h-5 text-green-600" />}
              link="/marketplace/sellers"
            />
          )}
        </div>
      </div>

      {/* 4. Detailed Insights Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <ActivityFeed />

        <div className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm">
          <h3 className="font-semibold mb-4 text-slate-800">
            Upcoming Events
          </h3>
          <div className="flex flex-col items-center justify-center py-10 text-center">
            <Calendar className="w-12 h-12 text-slate-200 mb-3" />
            <p className="text-sm text-slate-500">
              No community events scheduled for this week.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
